"""One-shot source migration for EUAS secure bearer-session storage.

This script is intentionally assertion-heavy: it only applies to the exact
baseline blocks it was designed for. The temporary workflow that invokes it
removes both itself and this script from the resulting product commit.
"""
from __future__ import annotations

from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def replace_once(path: str, old: str, new: str) -> None:
    target = ROOT / path
    text = target.read_text(encoding="utf-8")
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f"{path}: expected exactly one migration anchor, found {count}")
    target.write_text(text.replace(old, new, 1), encoding="utf-8")


def write(path: str, content: str) -> None:
    target = ROOT / path
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(content, encoding="utf-8")


replace_once("app/config.py", "SCHEMA_VERSION = 9", "SCHEMA_VERSION = 10")

