write(
    "tests/test_session_security.py",
    '''from __future__ import annotations\n\nimport hashlib\nfrom datetime import datetime, timedelta\n\nfrom fastapi.testclient import TestClient\n\nfrom app.auth import LEGACY_PBKDF2_ROUNDS, PBKDF2_ALGORITHM, PBKDF2_ROUNDS, session_token_hash\nfrom app.database import db, now\nfrom app.main import app\n\n\ndef _user_id(username: str = 'omar') -> int:\n    with db() as conn:\n        row = conn.execute('SELECT id FROM users WHERE username=?', (username,)).fetchone()\n        assert row\n        return int(row['id'])\n\n\ndef _clear_sessions(user_id: int) -> None:\n    with db() as conn:\n        conn.execute('DELETE FROM secure_sessions WHERE user_id=?', (user_id,))\n        conn.execute('DELETE FROM sessions WHERE user_id=?', (user_id,))\n\n\ndef _login(client: TestClient, username: str = 'omar', password: str = 'EUAS@2026') -> str:\n    response = client.post('/api/auth/login', json={'username': username, 'password': password})\n    assert response.status_code == 200, response.text\n    return response.json()['token']\n\n\ndef test_new_session_stores_digest_not_bearer_secret():\n    with TestClient(app) as client:\n        uid = _user_id();_clear_sessions(uid)\n        token = _login(client)\n        digest = session_token_hash(token)\n        with db() as conn:\n            assert conn.execute('SELECT token FROM sessions WHERE token=?', (token,)).fetchone() is None\n            stored = conn.execute('SELECT session_id,token_hash FROM secure_sessions WHERE user_id=?', (uid,)).fetchone()\n            assert stored is not None\n            assert stored['token_hash'] == digest\n            assert stored['token_hash'] != token\n            assert token not in stored['session_id']\n        me = client.get('/api/auth/me', headers={'Authorization': f'Bearer {token}'})\n        assert me.status_code == 200\n        sessions = client.get('/api/auth/sessions', headers={'Authorization': f'Bearer {token}'})\n        assert sessions.status_code == 200\n        assert len(sessions.json()) == 1\n        assert sessions.json()[0]['current'] is True\n        assert sessions.json()[0]['legacy'] is False\n        assert token not in sessions.text\n\n\ndef test_legacy_raw_session_is_migrated_on_first_use():\n    with TestClient(app) as client:\n        uid = _user_id();_clear_sessions(uid)\n        token = 'legacy-session-secret-for-regression'\n        created = now();expires = (datetime.now() + timedelta(hours=1)).isoformat(timespec='seconds')\n        with db() as conn:\n            conn.execute('INSERT INTO sessions(token,user_id,created_at,expires_at) VALUES(?,?,?,?)', (token,uid,created,expires))\n        response = client.get('/api/auth/me', headers={'Authorization': f'Bearer {token}'})\n        assert response.status_code == 200, response.text\n        with db() as conn:\n            assert conn.execute('SELECT token FROM sessions WHERE token=?', (token,)).fetchone() is None\n            migrated = conn.execute('SELECT token_hash,created_at,expires_at FROM secure_sessions WHERE user_id=?', (uid,)).fetchone()\n            assert migrated is not None\n            assert migrated['token_hash'] == session_token_hash(token)\n            assert migrated['created_at'] == created\n            assert migrated['expires_at'] == expires\n\n\ndef test_revoke_others_preserves_only_current_digest_session():\n    with TestClient(app) as client:\n        uid = _user_id();_clear_sessions(uid)\n        first = _login(client);second = _login(client)\n        response = client.post('/api/auth/sessions/revoke-others', headers={'Authorization': f'Bearer {second}'})\n        assert response.status_code == 200, response.text\n        assert response.json()['revoked'] == 1\n        assert client.get('/api/auth/me', headers={'Authorization': f'Bearer {first}'}).status_code == 401\n        assert client.get('/api/auth/me', headers={'Authorization': f'Bearer {second}'}).status_code == 200\n        with db() as conn:\n            rows = conn.execute('SELECT token_hash FROM secure_sessions WHERE user_id=?', (uid,)).fetchall()\n            assert len(rows) == 1\n            assert rows[0]['token_hash'] == session_token_hash(second)\n\n\ndef test_successful_login_upgrades_legacy_password_hash():\n    with TestClient(app) as client:\n        uid = _user_id('tech2');_clear_sessions(uid)\n        password = 'Tech2@2026';salt = 'legacy-login-upgrade'\n        digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt.encode(), LEGACY_PBKDF2_ROUNDS).hex()\n        legacy = f'{salt}${digest}'\n        with db() as conn:\n            original = conn.execute('SELECT password_hash FROM users WHERE id=?', (uid,)).fetchone()['password_hash']\n            conn.execute('UPDATE users SET password_hash=? WHERE id=?', (legacy,uid))\n        try:\n            token = _login(client, 'tech2', password)\n            with db() as conn:\n                upgraded = conn.execute('SELECT password_hash FROM users WHERE id=?', (uid,)).fetchone()['password_hash']\n                assert upgraded.startswith(f'{PBKDF2_ALGORITHM}${PBKDF2_ROUNDS}$')\n                assert upgraded != legacy\n                assert conn.execute('SELECT token_hash FROM secure_sessions WHERE token_hash=?', (session_token_hash(token),)).fetchone()\n        finally:\n            with db() as conn:\n                conn.execute('UPDATE users SET password_hash=? WHERE id=?', (original,uid))\n                conn.execute('DELETE FROM secure_sessions WHERE user_id=?', (uid,))\n                conn.execute('DELETE FROM sessions WHERE user_id=?', (uid,))\n''',
)

